// S1 · "Parse Config" (Code node, mode: Run Once for All Items)
// Turns the Config tab rows (key,value) into ONE settings object for this run.
const rows = $input.all().map(i => i.json);
const cfg = {};
for (const r of rows) {
  if (r.key) cfg[String(r.key).trim()] = String(r.value ?? '').trim();
}
const num = (v, d) => { const n = parseInt(v, 10); return Number.isFinite(n) ? n : d; };

return [{
  json: {
    // 'csv' (safe default) or 'apify'
    mode: (cfg.SCRAPER_MODE || 'csv').toLowerCase(),
    // "ai automation, smallbusiness" -> ["ai automation","smallbusiness"]
    hashtags: (cfg.HASHTAGS || '').split(',').map(h => h.trim().replace(/^#/, '').replace(/\s+/g, '')).filter(Boolean),
    postsLimit: num(cfg.POSTS_LIMIT, 20),
    // Hard ceiling of 300 profiles per run (assignment rule: a few hundred max)
    maxProfiles: Math.min(num(cfg.MAX_PROFILES, 100), 300),
  },
}];

// S1 · "Collect Usernames" (Code node, Run Once for All Items)
// Input: hashtag POSTS from the scraper. Output: ONE item with a de-duplicated
// list of post-owner usernames, capped at maxProfiles.
// Field names (ownerUsername / owner.username) come from the example workflows;
// VERIFY them against your real actor output (Apify run -> Output tab).
const { maxProfiles } = $('Parse Config').first().json;
const seen = new Set();

for (const it of $input.all()) {
  const p = it.json || {};
  const u = String(p.ownerUsername || (p.owner && p.owner.username) || '')
    .trim().toLowerCase().replace(/^@/, '');
  if (u) seen.add(u);
  if (seen.size >= maxProfiles) break;
}

// Throwing sends this node's ERROR output -> CSV fallback branch.
if (seen.size === 0) throw new Error('Scraper returned no usernames - using CSV fallback');

return [{ json: { usernames: [...seen] } }];

// S1 · "Normalize To Lead Shape" (Code node, Run Once for All Items)
// BOTH paths (Apify profiles and the CSV fallback) end here, so everything
// downstream sees the SAME "standard lead object":
// ig_user_id, username, source, followers, bio, email, website, niche, score, tier
// Apify field names (id, username, followersCount, biography, externalUrl) are
// assumptions based on the sample workflows - VERIFY on a real output item.
const toInt = v => {
  const n = parseInt(String(v ?? '').replace(/[^0-9]/g, ''), 10);
  return Number.isFinite(n) ? n : 0;
};

const out = [];
for (const it of $input.all()) {
  const p = it.json || {};
  const username = String(p.username || p.ownerUsername || '')
    .trim().toLowerCase().replace(/^@/, '');
  if (!username) continue; // skip rows with no username (e.g. empty items)

  out.push({
    json: {
      ig_user_id: String(p.ig_user_id || p.id || ''),
      username,
      source: 'scrape',
      followers: toInt(p.followers ?? p.followersCount),
      bio: String(p.bio ?? p.biography ?? '').trim(),
      email: String(p.email || p.businessEmail || '').trim().toLowerCase(),
      website: String(p.website || p.externalUrl || '').trim(),
      niche: '',
      score: '',
      tier: '',
    },
  });
}
// Hard safety cap (assignment: a few hundred profiles per run at most)
return out.slice(0, 300);
